[CmdletBinding()]param([ValidateSet('All','Publication','Verifier','FinalGate')][string]$Focus='All')
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
try{Add-Type -AssemblyName System.Security -ErrorAction Stop}catch{throw 'pkcs_runtime_unavailable'}
$root=Split-Path -Parent (Split-Path -Parent $PSScriptRoot);$manifest=Join-Path $root 'evidence/phase1/security-closure.yaml';$verifier=Join-Path $root 'scripts/verify-phase1-security.ps1';$capture=Join-Path $root 'scripts/add-security-closure-review.ps1'
function Assert($condition,$message){if(!$condition){throw "FAILED: $message"}}
function FileHash($path){$s=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($s.ComputeHash([IO.File]::ReadAllBytes($path)))).Replace('-','')}finally{$s.Dispose()}}
function HashText($value){$s=[Security.Cryptography.SHA256]::Create();try{$json=($value|ConvertTo-Json -Depth 20 -Compress)-replace"`r`n","`n";$bytes=[Text.UTF8Encoding]::new($false).GetBytes($json);([BitConverter]::ToString($s.ComputeHash($bytes))).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function HashBytes([byte[]]$bytes){[byte[]]$data=[byte[]]::new(0);if($null-ne$bytes){$data=$bytes};$s=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($s.ComputeHash($data,0,$data.Length))).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function Body($a){[ordered]@{threat_id=[string]$a.threat_id;payload_digest=[string]$a.payload_digest;reviewer_identity=$a.reviewer_identity;review_utc=[string]$a.review_utc;procedure_version=[string]$a.procedure_version;environment_fingerprint=$a.environment_fingerprint;previous_attestation_digest=[string]$a.previous_attestation_digest}}
function ArchiveBody($e){[ordered]@{schema_version=[string]$e.schema_version;threat_id=[string]$e.threat_id;payload_digest=[string]$e.payload_digest;history_entries=@($e.history_entries|%{[ordered]@{attestation_digest=[string]$_.attestation_digest;signature_cms_sha256=[string]$_.signature_cms_sha256}});history_count=[int]$e.history_count;latest_attestation_digest=[string]$e.latest_attestation_digest;reviewer_identity=$e.reviewer_identity;review_utc=[string]$e.review_utc;procedure_version=[string]$e.procedure_version;environment_fingerprint=$e.environment_fingerprint}}
function HistoryEntries($history){@($history|%{$property=$_.PSObject.Properties['signature_cms_base64'];[byte[]]$bytes=if($property-and![string]::IsNullOrWhiteSpace([string]$property.Value)){[Convert]::FromBase64String([string]$property.Value)}else{[byte[]]@()};[ordered]@{attestation_digest=[string]$_.attestation_digest;signature_cms_sha256=HashBytes ([byte[]]$bytes)}})}
function Invoke-Verify($path,[string[]]$extra=@()){$out=[IO.Path]::GetTempFileName();$err=[IO.Path]::GetTempFileName();try{$args=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$verifier,'-ClosurePath',$path,'-DiagnosticFormat','Json')+$extra;$p=Start-Process powershell -ArgumentList $args -Wait -PassThru -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err;[pscustomobject]@{Exit=$p.ExitCode;Out=(Get-Content -Raw $out);Err=(Get-Content -Raw $err)}}finally{Remove-Item $out,$err -Force -ErrorAction SilentlyContinue}}
function Invoke-FinalGate($scriptPath){$out=[IO.Path]::GetTempFileName();$err=[IO.Path]::GetTempFileName();try{$args=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$scriptPath,'-CallerMachine','hungdinh-lt','-ServerMachine','LAB-DC01','-SecondaryDcMachine','LAB-DC02','-EndpointMachine','LAB-CLIENT01','-TrustedRootPath',$env:PHASE1_TRUSTED_ROOT_PATH,'-ReviewerPolicyPath',$env:PHASE1_REVIEWER_POLICY_PATH);$p=Start-Process powershell -ArgumentList $args -Wait -PassThru -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err;[pscustomobject]@{Exit=$p.ExitCode;Out=(Get-Content -Raw $out);Err=(Get-Content -Raw $err)}}finally{Remove-Item $out,$err -Force -ErrorAction SilentlyContinue}}
function Mutate([scriptblock]$change){$p=Join-Path $env:TEMP("closure-$([guid]::NewGuid()).json");$c=Get-Content -Raw $manifest|ConvertFrom-Json;&$change $c;[IO.File]::WriteAllText($p,($c|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$p}
function RelativeToRoot([string]$path){$base=[IO.Path]::GetFullPath($root).TrimEnd([IO.Path]::DirectorySeparatorChar)+[IO.Path]::DirectorySeparatorChar;$full=[IO.Path]::GetFullPath($path);if(!$full.StartsWith($base,[StringComparison]::OrdinalIgnoreCase)){throw 'test_path_outside_root'};$full.Substring($base.Length)}
function Start-Publisher($path,$threat,$thumbprint,$policyPath,[string[]]$extra=@()){
 $stdin=Join-Path $env:TEMP("publisher-stdin-$([guid]::NewGuid()).txt");$stdout=Join-Path $env:TEMP("publisher-out-$([guid]::NewGuid()).txt");$stderr=Join-Path $env:TEMP("publisher-err-$([guid]::NewGuid()).txt");$exitPath=Join-Path $env:TEMP("publisher-exit-$([guid]::NewGuid()).txt")
 [IO.File]::WriteAllText($stdin,"YES`r`n",[Text.UTF8Encoding]::new($false));$quote={param($value)"'"+([string]$value).Replace("'","''")+"'"};$extraTokens=@();foreach($token in $extra){if(([string]$token).StartsWith('-')){$extraTokens+=[string]$token}else{$extraTokens+=&$quote $token}};$invocation="& '$($capture.Replace("'","''"))' -ClosurePath $(&$quote $path) -ThreatId $(&$quote $threat) -ReviewerPolicyPath $(&$quote $policyPath) -SignerThumbprint $(&$quote $thumbprint) $($extraTokens-join' ')";$command="`$code=0;try{$invocation;if(-not `$?){`$code=1}}catch{[Console]::Error.WriteLine(`$_.Exception.Message);`$code=1}finally{[IO.File]::WriteAllText('$($exitPath.Replace("'","''"))',[string]`$code)};exit `$code";$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($command))
 $process=Start-Process powershell -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-EncodedCommand',$encoded) -PassThru -NoNewWindow -RedirectStandardInput $stdin -RedirectStandardOutput $stdout -RedirectStandardError $stderr
 [pscustomobject]@{Process=$process;Input=$stdin;Output=$stdout;Error=$stderr;ExitPath=$exitPath}
}
function Wait-Publisher($publisher,[int]$timeoutSeconds=15){
 if(!$publisher.Process.WaitForExit($timeoutSeconds*1000)){try{$publisher.Process.Kill()}catch{};throw 'FAILED: publisher timed out'};$publisher.Process.WaitForExit();$publisher.Process.Refresh()
 Assert (Test-Path $publisher.ExitPath) 'publisher wrapper captured exit code';[pscustomobject]@{ExitCode=[int](Get-Content -Raw $publisher.ExitPath);Out=(Get-Content -Raw $publisher.Output -ErrorAction SilentlyContinue);Err=(Get-Content -Raw $publisher.Error -ErrorAction SilentlyContinue)}
}
function Remove-Publisher($publisher){Remove-Item $publisher.Input,$publisher.Output,$publisher.Error,$publisher.ExitPath -Force -ErrorAction SilentlyContinue}
function New-PublicationTestCertificate {
 $rsa=[Security.Cryptography.RSA]::Create(2048);$request=[Security.Cryptography.X509Certificates.CertificateRequest]::new('CN=Phase1 Publication Test Reviewer',$rsa,[Security.Cryptography.HashAlgorithmName]::SHA256,[Security.Cryptography.RSASignaturePadding]::Pkcs1)
 $request.CertificateExtensions.Add([Security.Cryptography.X509Certificates.X509KeyUsageExtension]::new([Security.Cryptography.X509Certificates.X509KeyUsageFlags]::DigitalSignature,$true));$certificate=$request.CreateSelfSigned([DateTimeOffset]::UtcNow.AddMinutes(-5),[DateTimeOffset]::UtcNow.AddHours(1));$flags=[Security.Cryptography.X509Certificates.X509KeyStorageFlags]::PersistKeySet-bor[Security.Cryptography.X509Certificates.X509KeyStorageFlags]::UserKeySet;$persisted=[Security.Cryptography.X509Certificates.X509Certificate2]::new($certificate.Export([Security.Cryptography.X509Certificates.X509ContentType]::Pfx),$null,$flags)
 $store=[Security.Cryptography.X509Certificates.X509Store]::new('My',[Security.Cryptography.X509Certificates.StoreLocation]::CurrentUser);try{$store.Open([Security.Cryptography.X509Certificates.OpenFlags]::ReadWrite);$store.Add($persisted)}finally{$store.Dispose();$certificate.Dispose();$rsa.Dispose()};$persisted
}
function Remove-PublicationTestCertificate($certificate){$store=[Security.Cryptography.X509Certificates.X509Store]::new('My',[Security.Cryptography.X509Certificates.StoreLocation]::CurrentUser);try{$store.Open([Security.Cryptography.X509Certificates.OpenFlags]::ReadWrite);$store.Remove($certificate)}finally{$store.Dispose();$certificate.Dispose()}}
function New-VerifierTestCertificate([switch]$DigitalSignature,[string]$EkuOid){$rsa=[Security.Cryptography.RSA]::Create(2048);$request=[Security.Cryptography.X509Certificates.CertificateRequest]::new('CN=Phase1 Verifier Test Reviewer',$rsa,[Security.Cryptography.HashAlgorithmName]::SHA256,[Security.Cryptography.RSASignaturePadding]::Pkcs1);if($DigitalSignature){$request.CertificateExtensions.Add([Security.Cryptography.X509Certificates.X509KeyUsageExtension]::new([Security.Cryptography.X509Certificates.X509KeyUsageFlags]::DigitalSignature,$true))};if($EkuOid){$oids=[Security.Cryptography.OidCollection]::new();$null=$oids.Add([Security.Cryptography.Oid]::new($EkuOid));$request.CertificateExtensions.Add([Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension]::new($oids,$true))};$certificate=$request.CreateSelfSigned([DateTimeOffset]::UtcNow.AddMinutes(-5),[DateTimeOffset]::UtcNow.AddHours(1));$rsa.Dispose();$certificate}
function Sign-TestBody($body,$certificate){$bytes=[Text.UTF8Encoding]::new($false).GetBytes((($body|ConvertTo-Json -Depth 20 -Compress)-replace"`r`n","`n"));$cms=[Security.Cryptography.Pkcs.SignedCms]::new([Security.Cryptography.Pkcs.ContentInfo]::new($bytes),$true);$signer=[Security.Cryptography.Pkcs.CmsSigner]::new($certificate);$signer.IncludeOption='EndCertOnly';$cms.ComputeSignature($signer);[Convert]::ToBase64String($cms.Encode())}
function New-VerifierFixture($certificate,[string]$requiredEku){$dir=Join-Path $env:TEMP("verifier-fixture-$([guid]::NewGuid())");New-Item -ItemType Directory -Path $dir|Out-Null;$closurePath=Join-Path $dir 'closure.json';$rootPath=Join-Path $dir 'root.cer';$policyPath=Join-Path $dir 'policy.json';$closure=Get-Content -Raw $manifest|ConvertFrom-Json;$record=$closure.records[0];$record.PSObject.Properties.Remove('superseded_payload_history');$history=@($record.attestations);$previous='';foreach($attestation in $history){$attestation.previous_attestation_digest=$previous;$hasCms=$attestation.PSObject.Properties['signature_cms_base64'] -and ![string]::IsNullOrWhiteSpace([string]$attestation.signature_cms_base64);if($hasCms){$attestation.reviewer_identity=[pscustomobject]@{kind='independent_verifier';name='verifier-test-reviewer'};$attestation.review_utc=[DateTime]::UtcNow.ToString('o');$attestation.procedure_version='phase1-verifier-test/v1';$attestation.environment_fingerprint=[pscustomobject]@{machine_identity='verifier-test';role='independent_reviewer';domain_network_identity='test.local'}};$attestation.attestation_digest=HashText (Body $attestation);if($hasCms){$attestation.signature_cms_base64=Sign-TestBody (Body $attestation) $certificate};$previous=[string]$attestation.attestation_digest};$envelope=[ordered]@{schema_version='phase1-history-envelope/v1';threat_id=[string]$record.threat_id;payload_digest=[string]$record.payload_digest;history_entries=HistoryEntries $history;history_count=$history.Count;latest_attestation_digest=[string]$history[-1].attestation_digest;reviewer_identity=[pscustomobject]@{kind='independent_verifier';name='verifier-test-reviewer'};review_utc=[DateTime]::UtcNow.ToString('o');procedure_version='phase1-verifier-test/v1';environment_fingerprint=[pscustomobject]@{machine_identity='verifier-test';role='independent_reviewer';domain_network_identity='test.local'}};$envelope.envelope_digest=HashText (ArchiveBody $envelope);$envelope.signature_cms_base64=Sign-TestBody (ArchiveBody $envelope) $certificate;$record|Add-Member -NotePropertyName history_envelope -NotePropertyValue ([pscustomobject]$envelope) -Force;[IO.File]::WriteAllText($closurePath,($closure|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllBytes($rootPath,$certificate.Export([Security.Cryptography.X509Certificates.X509ContentType]::Cert));$policy=[ordered]@{schema_version='phase1-reviewer-policy/v1';policy_id='verifier-test';procedure_version='phase1-verifier-test/v1';max_clock_skew_seconds=300;required_eku_oids=@($requiredEku);reviewers=@([ordered]@{identity='verifier-test-reviewer';thumbprint=$certificate.Thumbprint;machine_identity='verifier-test';role='independent_reviewer';domain_network_identity='test.local'})};[IO.File]::WriteAllText($policyPath,($policy|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));[pscustomobject]@{Directory=$dir;Closure=$closurePath;Root=$rootPath;Policy=$policyPath;Threat=[string]$record.threat_id}}

function Invoke-IndexValidation($store){$script=Join-Path $root 'scripts/add-independent-review.ps1';$out=[IO.Path]::GetTempFileName();$err=[IO.Path]::GetTempFileName();try{$args=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$script,'-ReviewerPolicyPath','unused','-ReviewerRootPath','unused','-ArchivalPolicyPath','unused','-SignerThumbprint','00','-ReviewStorePath',$store,'-ValidateIndexOnly');$p=Start-Process powershell -ArgumentList $args -Wait -PassThru -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err;[pscustomobject]@{Exit=$p.ExitCode;Text=(Get-Content -Raw $out)+(Get-Content -Raw $err)}}finally{Remove-Item $out,$err -Force -ErrorAction SilentlyContinue}}
if($Focus-in@('All','Publication')){
 $indexFixture=Join-Path $env:TEMP("d48-index-$([guid]::NewGuid())");Copy-Item (Join-Path $root 'evidence/phase1/independent-reviews') $indexFixture -Recurse;try{$validIndex=Invoke-IndexValidation $indexFixture;Assert ($validIndex.Exit-eq0) "canonical D-48 index validates: $($validIndex.Text)";$tampered=Get-Content -Raw (Join-Path $indexFixture 'index.json')|ConvertFrom-Json;$tampered.generations[0].generation_digest='0'*64;[IO.File]::WriteAllText((Join-Path $indexFixture 'index.json'),($tampered|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$result=Invoke-IndexValidation $indexFixture;Assert ($result.Exit-ne0-and$result.Text-match'd48_index_(order|generation_digest)_invalid') 'tampered index digest is rejected';Copy-Item (Join-Path $root 'evidence/phase1/independent-reviews/index.json') (Join-Path $indexFixture 'index.json') -Force;$truncated=[ordered]@{schema_version='phase1-independent-review-index/v1';generations=@()};[IO.File]::WriteAllText((Join-Path $indexFixture 'index.json'),($truncated|ConvertTo-Json -Compress),[Text.UTF8Encoding]::new($false));$result=Invoke-IndexValidation $indexFixture;Assert ($result.Exit-ne0-and$result.Text-match'd48_index_truncation_or_fork') 'truncated index is rejected';Copy-Item (Join-Path $root 'evidence/phase1/independent-reviews/index.json') (Join-Path $indexFixture 'index.json') -Force;New-Item -ItemType Directory (Join-Path $indexFixture '000002-fork')|Out-Null;$result=Invoke-IndexValidation $indexFixture;Assert ($result.Exit-ne0-and$result.Text-match'd48_index_truncation_or_fork') 'forked generation directory is rejected'}finally{Remove-Item $indexFixture -Recurse -Force -ErrorAction SilentlyContinue}
 $publicationRoot=Join-Path $env:TEMP("phase1-publication-$([guid]::NewGuid())");New-Item -ItemType Directory -Path $publicationRoot|Out-Null
 $certificate=New-PublicationTestCertificate
 $observedIdentity=[Security.Principal.WindowsIdentity]::GetCurrent().Name
 $policyPath=Join-Path $publicationRoot 'reviewer-policy.json';$policy=[ordered]@{procedure_version='phase1-publication-test/v1';reviewers=@([ordered]@{thumbprint=$certificate.Thumbprint;identity=$observedIdentity;machine_identity=$env:COMPUTERNAME;role='independent_security_reviewer';domain_network_identity='test.local'})};[IO.File]::WriteAllText($policyPath,($policy|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false))
 try{
   $threat='T-01-15-03'
   foreach($mismatch in @(
    @{Name='identity';Code='reviewer_identity_mismatch';Identity='LAB\not-the-executing-user';Machine=$env:COMPUTERNAME},
    @{Name='machine';Code='reviewer_machine_mismatch';Identity=$observedIdentity;Machine='LAB-DC99'}
   )){
    $mismatchPath=Join-Path $publicationRoot ("mismatch-$($mismatch.Name).json");Copy-Item $manifest $mismatchPath;$beforeMismatch=FileHash $mismatchPath
    $mismatchPolicyPath=Join-Path $publicationRoot ("mismatch-$($mismatch.Name)-policy.json");$mismatchPolicy=[ordered]@{procedure_version='phase1-publication-test/v1';reviewers=@([ordered]@{thumbprint=$certificate.Thumbprint;identity=$mismatch.Identity;machine_identity=$mismatch.Machine;role='independent_security_reviewer';domain_network_identity='test.local'})};[IO.File]::WriteAllText($mismatchPolicyPath,($mismatchPolicy|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false))
    $publisher=Start-Publisher $mismatchPath $threat $certificate.Thumbprint $mismatchPolicyPath;try{$result=Wait-Publisher $publisher;Assert ($result.ExitCode-ne0) "$($mismatch.Name) mismatch is rejected";Assert (($result.Out+$result.Err)-match$mismatch.Code) "$($mismatch.Name) mismatch has stable diagnostic";Assert (($result.Out+$result.Err)-notmatch 'Attest exact complete payload') "$($mismatch.Name) mismatch fails before consent prompt";Assert ((FileHash $mismatchPath)-eq$beforeMismatch) "$($mismatch.Name) mismatch leaves manifest byte-identical";Assert (@(Get-ChildItem $publicationRoot -Filter ".mismatch-$($mismatch.Name).json.*.tmp").Count-eq0) "$($mismatch.Name) mismatch creates no temporary publication file"}finally{Remove-Publisher $publisher}
   }

   $observedPath=Join-Path $publicationRoot 'observed.json';Copy-Item $manifest $observedPath;$observedPublisher=Start-Publisher $observedPath $threat $certificate.Thumbprint $policyPath;try{$observedResult=Wait-Publisher $observedPublisher;Assert ($observedResult.ExitCode-eq0) "observed execution context publishes: $($observedResult.Out) $($observedResult.Err)";$observedClosure=Get-Content -Raw $observedPath|ConvertFrom-Json;$published=@((@($observedClosure.records|Where-Object threat_id -eq $threat))[0].attestations)[-1];Assert ([string]$published.reviewer_identity.name-eq$observedIdentity) 'attestation records observed Windows identity';Assert ([string]$published.environment_fingerprint.machine_identity-eq$env:COMPUTERNAME) 'attestation records observed machine identity'}finally{Remove-Publisher $observedPublisher}
  $driftPath=Join-Path $publicationRoot 'drift.json';Copy-Item $manifest $driftPath;$barrier=Join-Path $publicationRoot 'drift-barrier';New-Item -ItemType File -Path "$barrier.wait"|Out-Null
  $driftPublisher=Start-Publisher $driftPath $threat $certificate.Thumbprint $policyPath @('-PublicationBarrierPath',$barrier)
  try{for($i=0;$i-lt150-and!(Test-Path $barrier);$i++){Start-Sleep -Milliseconds 50};if(!(Test-Path $barrier)){$early=Wait-Publisher $driftPublisher;throw "FAILED: drift publisher acquired publication lock: $($early.Out) $($early.Err)"};$drift=Get-Content -Raw $driftPath|ConvertFrom-Json;(@($drift.records|Where-Object threat_id -eq $threat))[0].mitigation_assertion+=' concurrent mutation';[IO.File]::WriteAllText($driftPath,($drift|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$mutatedHash=FileHash $driftPath;Remove-Item "$barrier.wait" -Force;$driftResult=Wait-Publisher $driftPublisher;Assert ($driftResult.ExitCode-ne0) 'protected-field drift is rejected';Assert (($driftResult.Out+$driftResult.Err)-match"publication_conflict:$threat") 'protected-field drift has stable diagnostic';Assert ((FileHash $driftPath)-eq$mutatedHash) 'rejected drift leaves manifest byte-identical'}finally{Remove-Item "$barrier.wait" -Force -ErrorAction SilentlyContinue;Remove-Publisher $driftPublisher}

  $racePath=Join-Path $publicationRoot 'race.json';Copy-Item $manifest $racePath;$raceInitial=Get-Content -Raw $racePath|ConvertFrom-Json;$raceInitialAttestations=@((@($raceInitial.records|Where-Object threat_id -eq $threat))[0].attestations);$raceInitialPredecessor=[string]$raceInitialAttestations[-1].attestation_digest;$raceBarrier=Join-Path $publicationRoot 'race-barrier';New-Item -ItemType File -Path "$raceBarrier.wait"|Out-Null
  $first=Start-Publisher $racePath $threat $certificate.Thumbprint $policyPath @('-PublicationBarrierPath',$raceBarrier)
  try{for($i=0;$i-lt150-and!(Test-Path $raceBarrier);$i++){Start-Sleep -Milliseconds 50};Assert (Test-Path $raceBarrier) 'first publisher acquired publication lock';$second=Start-Publisher $racePath $threat $certificate.Thumbprint $policyPath;Start-Sleep -Milliseconds 500;Remove-Item "$raceBarrier.wait" -Force;$firstResult=Wait-Publisher $first;$secondResult=Wait-Publisher $second;Assert ($firstResult.ExitCode-eq0) "one concurrent publisher succeeds (exit $($firstResult.ExitCode)): $($firstResult.Out) $($firstResult.Err)";Assert ($secondResult.ExitCode-ne0) 'stale concurrent publisher is rejected';Assert (($secondResult.Out+$secondResult.Err)-match"publication_conflict:$threat") 'stale publisher has stable diagnostic';$race=Get-Content -Raw $racePath|ConvertFrom-Json;$raceAttestations=@((@($race.records|Where-Object threat_id -eq $threat))[0].attestations);Assert ($raceAttestations.Count-eq($raceInitialAttestations.Count+1)) 'exactly one concurrent attestation is published';Assert ([string]$raceAttestations[-1].previous_attestation_digest-eq$raceInitialPredecessor) 'published attestation preserves predecessor chain'}finally{Remove-Item "$raceBarrier.wait" -Force -ErrorAction SilentlyContinue;Remove-Publisher $first;if($second){Remove-Publisher $second}}

  $crashPath=Join-Path $publicationRoot 'crash.json';Copy-Item $manifest $crashPath;$beforeCrash=FileHash $crashPath;$crash=Start-Publisher $crashPath $threat $certificate.Thumbprint $policyPath @('-CrashBeforeReplace');try{$crashResult=Wait-Publisher $crash;Assert ($crashResult.ExitCode-ne0) 'injected pre-replace crash fails';Assert (($crashResult.Out+$crashResult.Err)-match'injected_crash_before_replace') 'injected crash has stable diagnostic';Assert ((FileHash $crashPath)-eq$beforeCrash) 'injected crash preserves original manifest bytes';Assert (@(Get-ChildItem $publicationRoot -Filter '.crash.json.*.tmp').Count-eq0) 'injected crash removes publication temporary files'}finally{Remove-Publisher $crash}
 }finally{Remove-PublicationTestCertificate $certificate;Remove-Item $publicationRoot -Recurse -Force -ErrorAction SilentlyContinue}
}

if($Focus-eq'Publication'){Write-Host 'Phase 1 publication security tests passed.';exit 0}

if($Focus-in@('All','FinalGate')){
 $evidenceModule=Join-Path $root 'scripts/evidence/Phase1.Evidence.psm1';Import-Module $evidenceModule -Force
 $independentIndex=Join-Path $root 'evidence/phase1/independent-reviews/index.json';$independentPolicy=Join-Path $root 'evidence-private/phase1/d48-reviewer-policy.json';$independentRoot=Join-Path $root 'evidence-private/phase1/d48-reviewer-root.cer';$archivalPolicy=Join-Path $root 'evidence-private/phase1/reviewer-policy.json'
 if((Test-Path $independentIndex)-and(Test-Path $independentPolicy)-and(Test-Path $independentRoot)-and(Test-Path $archivalPolicy)){
  $legacyResult=Test-Phase1IndependentReview -RepositoryRoot $root -IndexPath $independentIndex -ReviewerPolicyPath $independentPolicy -ReviewerRootPath $independentRoot -ArchivalPolicyPath $archivalPolicy;Assert (@($legacyResult.Errors)-notcontains'd48_pkcs_assembly_missing') 'independent review loads PKCS in the module process';Assert (@($legacyResult.Errors)-notcontains'independent_review_archival_subject_missing') 'versioned legacy archival reviewer without subject reaches normal validation'
